{'name': '야간창문조명사이렌블라인드커튼문열림알람', 'cron': '0 22 * * *', 'period': 100, 'code': '
sirenActivated := false
curtainClosed := false
openCloseCount := 0
openCloseStartTime := 0
openCloseEndTime := 0
alarmOn := false

if ((#Window #하단부).windowControl_window == "open" and any(#Light #짝수).switch_switch == "on" and sirenActivated == false) {
    (#Siren).sirenMode_setSirenMode("siren")
    sirenActivated = true
    startTime := (#Clock).clock_timestamp
    (#Clock).clock_delay(5000)
    (#Blind).blind_close()
} 

if (sirenActivated == true) {
    count := openCloseCount
    timeStart := openCloseStartTime
    timeEnd := openCloseEndTime

    if (count >= 2 and curtainClosed == false) {
        (#Curtain).curtain_close()
        curtainClosed = true
        openCloseEndTime = (#Clock).clock_timestamp
        openCloseDuration = openCloseEndTime - timeStart
        (#Alarm).alarm_strobe()
        alarmOn = true
        alarmStartTime = (#Clock).clock_timestamp
    }

    if (alarmOn == true) {
        elapsedAlarm = (#Clock).clock_timestamp - alarmStartTime
        if (elapsedAlarm >= openCloseDuration) {
            (#Alarm).alarm_off()
            alarmOn = false
            openCloseCount = 0
            curtainClosed = false
            sirenActivated = false
        }
    }
}

// 실시간 문 열림 닫힘 감지 (짝수5초 후부터)
doorState := (#DoorLock #홀수).doorControl_door
prevDoorState := "closed"
triggered := false

if (sirenActivated or sirenActivated == false) {
    if (triggered == false) {
        if ((doorState == "open") and (prevDoorState == "closed")) {
            openCloseCount = openCloseCount + 1
            if (openCloseCount == 1) {
                openCloseStartTime = (#Clock).clock_timestamp
            }
            prevDoorState = "open"
            triggered = true
        } else if ((doorState == "closed") and (prevDoorState == "open")) {
            prevDoorState = "closed"
            triggered = true
        } else {
            triggered = false
        }
    } else {
        if (!((doorState == "open" and prevDoorState == "closed") or (doorState == "closed" and prevDoorState == "open"))) {
            triggered = false
        }
    }
}
'}

